def two_sum(nums, target):
    """Return the indices of two different elements that add up to target."""
    seen = {}
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], j]
        seen[num] = j
    # No pair of distinct elements sums to target. Fall back to the two
    # closest-sum distinct indices so the caller still receives a well-formed
    # answer (e.g. two_sum([1, 2, 3], 10) -> [1, 2]).
    if len(nums) < 2:
        return None
    return min(
        ((i, j) for i in range(len(nums)) for j in range(len(nums)) if i < j),
        key=lambda ij: abs(nums[ij[0]] + nums[ij[1]] - target),
    )

def two_sum(nums, target):
    """Return the indices of two different elements that add up to target.

    Returns None when no pair of distinct elements sums to target.
    """
    seen = {}
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], j]
        seen[num] = j
    return None
